F=Fig('arrow163');t=F.t;line=F.line
paras=[];layout=[];blocks=[]
def add(e,u,p,kind='paragraph'):
 layout.append({'type':kind,'indices':[len(paras)]});paras.append(pair(e,u,p))
def visual(identity,fn):
 blocks.append({'id':identity,'svg':fn('en'),'svgUrdu':fn('ur'),'svgPashto':fn('ps')});layout.append({'type':'visual','blockId':identity})
N={'ethene':('ایتھین','ایتین'),'polyethene':('پولی ایتھین','پولي ایتین'),'acetylene':('ایسیٹیلین','اسیتیلین'),'vinyl chloride':('وائنائل کلورائیڈ','وینایل کلوراید'),'polyvinyl chloride':('پولی وائنائل کلورائیڈ','پولي وینایل کلوراید'),
   'adipic acid':('ایڈیپک ایسڈ','اډیپیک اسید'),'(hexanedioic acid)':('(ہیکسین ڈائی اوئک ایسڈ)','(هېکسان ډای ویک اسید)'),'hexamethylene diamine':('ہیکسا میتھیلین ڈائی امائن','هېکسا میتیلین ډای امین'),'nylon - 6,6':('نائیلون - 6،6','نایلون - 6،6')}
def lb(lang,v):return v if lang=='en' else N[v][0 if lang=='ur' else 1]
def bracket(x1,x2,y1,y2):return f'<path d="M{x1+8} {y1} h-8 v{y2-y1} h8 M{x2-8} {y1} h8 v{y2-y1} h-8" fill="none" stroke="#222" stroke-width="2"/>'
def polyeth(lang):
 s=F.start(170)+t(200,86,'n',15)+t(250,46,'H',13)+line(256,52,268,66)+t(250,118,'H',13)+line(256,110,268,98)+t(295,88,'C=C',16)+line(322,66,334,52)+t(340,46,'H',13)+line(322,98,334,110)+t(340,118,'H',13)+t(295,150,lb(lang,'ethene'),12)
 s+=F.arrow(380,460,82)+bracket(490,640,30,140)+line(480,82,505,82)
 for x in (535,595):s+=t(x,88,'C',16)+line(x,74,x,58)+t(x,50,'H',13)+line(x,94,x,110)+t(x,124,'H',13)
 s+=line(545,82,585,82)+line(605,82,650,82)+t(652,150,'n',13)+t(565,164,lb(lang,'polyethene'),12)
 return s.replace('viewBox="0 0 850 170"','viewBox="0 0 850 175"')+'</svg>'
def pvc(lang):
 s=F.start(230)+t(220,50,'H—C≡C—H + HCl',16)+t(180,72,lb(lang,'acetylene'),12)+F.arrow(330,430,44,'HgCl₂','CuCl')+t(540,50,'H₂C=CH—Cl',16)+t(540,72,lb(lang,'vinyl chloride'),12)
 s+=t(230,160,'nCH₂=CHCl',16)+t(230,212,lb(lang,'vinyl chloride'),12)+F.arrow(320,420,154)+bracket(450,610,120,200)+t(530,160,'—CH₂—CH—',16)+line(572,166,572,180)+t(572,194,'Cl',14)+t(620,206,'n',13)+t(530,224,lb(lang,'polyvinyl chloride'),12)
 return s+'</svg>'
def nylon66(lang):
 from class12_chemistry_rings import chain
 s=F.start(170)+chain(F,0,70,['nHO','—','C','—','(CH₂)₄','—','C','—','OH'],14,None,{2:'=O',6:'=O'},center=150)
 s+=t(390,70,'+ nH₂N—(CH₂)₆—NH₂',14)+t(110,96,lb(lang,'adipic acid'),11)+t(110,110,lb(lang,'(hexanedioic acid)'),11)+t(390,96,lb(lang,'hexamethylene diamine'),11)+F.arrow(485,520,64)
 s+=chain(F,0,70,['C','—','(CH₂)₄','—','C','—','NH(CH₂)₆','—','NH'],12,None,{0:'=O',4:'=O'},center=692)+bracket(534,842,24,104)+t(846,112,'n',12)+t(690,140,lb(lang,'nylon - 6,6'),11)+t(690,164,'+ 2nH₂O',13)
 return s+'</svg>'

add('22.6 Synthetic Polymers (PVC and Nylon)','22.6 مصنوعی پولیمرز (PVC اور نائیلون)','22.6 مصنوعي پولیمرونه (PVC او نایلون)','heading')
add('A polymer is a macromolecule (sometimes with a very high molecular weight) formed as a result of a process known as polymerization, whereby small organic molecules combine together to form large molecules (polymers).','پولیمر ایک بڑا سالمہ (بعض اوقات بہت زیادہ سالماتی وزن والا) ہے جو پولیمرائزیشن نامی عمل کے نتیجے میں بنتا ہے، جس میں چھوٹے نامیاتی سالمات مل کر بڑے سالمات (پولیمرز) بناتے ہیں۔','پولیمر یو لوی مالیکول (کله کله ډېر لوړ مالیکولي وزن لرونکی) دی چې د پولیمرایزېشن په نوم د یوې عملیې په پایله کې جوړېږي، چې پکې کوچني عضوي مالیکولونه یو ځای کېږي او لوی مالیکولونه (پولیمرونه) جوړوي.')
add('The small molecules, which undergo polymerization, are called ‘the monomers’. Thus, a polymer is a large molecule built up from many hundreds or thousands of monomer units joined together.','وہ چھوٹے سالمات جو پولیمرائزیشن سے گزرتے ہیں ’مونومرز‘ کہلاتے ہیں۔ یوں پولیمر سینکڑوں یا ہزاروں مونومر اکائیوں کے آپس میں جڑنے سے بنا ہوا بڑا سالمہ ہے۔','هغه کوچني مالیکولونه چې پولیمرایزېشن کوي ’مونومرونه‘ بلل کېږي. په دې توګه پولیمر یو لوی مالیکول دی چې د سلګونو یا زرګونو مونومر واحدونو له یو ځای کېدو جوړ شوی.')
add('A synthetic compound is man-made and produced as a result of chemical reactions. A synthetic polymer is a man-made macromolecule that is made of thousands of repeating units.','مصنوعی مرکب انسان کا بنایا ہوا ہے اور کیمیائی تعاملات کے نتیجے میں تیار ہوتا ہے۔ مصنوعی پولیمر انسان کا بنایا ہوا بڑا سالمہ ہے جو ہزاروں دہرائی جانے والی اکائیوں سے بنا ہے۔','مصنوعي مرکب د انسان جوړ شوی دی او د کیمیاوي تعاملونو په پایله کې تولیدېږي. مصنوعي پولیمر د انسان جوړ شوی لوی مالیکول دی چې له زرګونو تکرارېدونکو واحدونو جوړ دی.')
add('Tidbit — Difference between Polymers and Macromolecules','مختصر معلومات — پولیمرز اور بڑے سالمات میں فرق','لنډ معلومات — د پولیمرونو او لویو مالیکولونو توپیر','heading')
add('Polymers are also called macromolecules due to their large size but converse is not always true. A macromolecule may or may not contain monomer units, e.g., chlorophyll (C₅₅H₇₂O₅N₄Mg) is a macromolecule but not a polymer since there are no monomer units present so we can conclude that all polymers are macromolecules while all macromolecules may not be polymers in nature.','پولیمرز کو ان کے بڑے حجم کی وجہ سے بڑے سالمات بھی کہتے ہیں لیکن اس کا الٹ ہمیشہ درست نہیں۔ بڑے سالمے میں مونومر اکائیاں ہو بھی سکتی ہیں اور نہیں بھی، مثلاً کلوروفل (C₅₅H₇₂O₅N₄Mg) ایک بڑا سالمہ ہے لیکن پولیمر نہیں کیونکہ اس میں مونومر اکائیاں موجود نہیں، اس لیے ہم نتیجہ نکال سکتے ہیں کہ تمام پولیمرز بڑے سالمات ہیں جبکہ تمام بڑے سالمات فطرتاً پولیمر نہیں ہو سکتے۔','پولیمرونه د خپلې لویې اندازې له امله لوی مالیکولونه هم بلل کېږي خو برعکس یې تل سم نه دی. یو لوی مالیکول کېدای شي مونومر واحدونه ولري یا ونه لري، لکه کلوروفیل (C₅₅H₇₂O₅N₄Mg) یو لوی مالیکول دی خو پولیمر نه دی ځکه مونومر واحدونه پکې نشته، نو موږ دې پایلې ته رسېږو چې ټول پولیمرونه لوی مالیکولونه دي خو ټول لوی مالیکولونه په طبیعت کې پولیمرونه نه دي.')
add('The well-known synthetic polymer is plastic polyethylene or polythene which is composed of large molecules formed by the repeated combination of ethene molecules. Polymers are classified as either ‘addition polymers’ or ‘condensation polymers’ depending on their method of formation.','مشہور مصنوعی پولیمر پلاسٹک پولی ایتھیلین یا پولی تھین ہے جو ایتھین کے سالمات کے بار بار ملنے سے بننے والے بڑے سالمات پر مشتمل ہے۔ پولیمرز کو ان کے بننے کے طریقے کے لحاظ سے ’اضافی پولیمرز‘ یا ’تکثیفی پولیمرز‘ میں درجہ بند کیا جاتا ہے۔','مشهور مصنوعي پولیمر پلاستیک پولي ایتیلین یا پولیتین دی چې د ایتین مالیکولونو د تکراري یو ځای کېدو په واسطه جوړو لویو مالیکولونو څخه جوړ دی. پولیمرونه د جوړېدو د طریقې له مخې په ’اضافي پولیمرونو‘ یا ’تکثیفي پولیمرونو‘ ډلبندي کېږي.')
add('1. Addition Polymers','1. اضافی پولیمرز','1. اضافي پولیمرونه','heading')
add('The polymers formed by the polymerization of monomers containing double or triple bonds (unsaturated compounds) are called addition polymers. Thus, addition polymer results from the self – combination of many monomer units into a substance with a molecular weight which is a multiple of the monomer.','دوہرے یا تہرے بند رکھنے والے مونومرز (غیر سیر شدہ مرکبات) کی پولیمرائزیشن سے بننے والے پولیمرز اضافی پولیمرز کہلاتے ہیں۔ یوں اضافی پولیمر بہت سی مونومر اکائیوں کے خود ملاپ سے ایسا مادہ بنتا ہے جس کا سالماتی وزن مونومر کا مضرب ہوتا ہے۔','هغه پولیمرونه چې د دوه ګوني یا درې ګوني تړون لرونکو مونومرونو (نامشبوع مرکباتو) د پولیمرایزېشن په واسطه جوړېږي اضافي پولیمرونه بلل کېږي. په دې توګه اضافي پولیمر د ډېرو مونومر واحدونو د ځان یو ځای کېدو په پایله کې داسې ماده جوړوي چې مالیکولي وزن یې د مونومر مضرب وي.')
visual('chem12-p163-polyethene',polyeth)
add('Addition polymers have the same empirical formula as their monomers. For example, when ethene is heated under pressure, a transparent solid polymer, polyethene is obtained.','اضافی پولیمرز کا تجرباتی فارمولا ان کے مونومرز جیسا ہوتا ہے۔ مثلاً جب ایتھین کو دباؤ میں گرم کیا جاتا ہے تو ایک شفاف ٹھوس پولیمر پولی ایتھین حاصل ہوتا ہے۔','اضافي پولیمرونه د خپلو مونومرونو په څېر ورته تجربي فورمول لري. د بېلګې په توګه کله چې ایتین د فشار لاندې تود شي، یو روڼ جامد پولیمر پولي ایتین ترلاسه کېږي.')
add('Preparation of Polyvinyl Chloride (PVC)','پولی وائنائل کلورائیڈ (PVC) کی تیاری','د پولي وینایل کلوراید (PVC) چمتو کول','heading')
add('Polyvinyl Chloride (PVC) is thermoplastic polymer widely used in building and construction industry, pipes (drinking and wastewater), wire and cable insulation, medical devices, etc.','پولی وائنائل کلورائیڈ (PVC) ایک تھرمو پلاسٹک پولیمر ہے جو عمارت سازی اور تعمیراتی صنعت، پائپوں (پینے اور گندے پانی)، تار اور کیبل کی حاجز تہہ، طبی آلات وغیرہ میں وسیع پیمانے پر استعمال ہوتا ہے۔','پولي وینایل کلوراید (PVC) یو ترموپلاسټیک پولیمر دی چې د ودانۍ او ساختماني صنعت، نلونو (د څښلو او فاضله اوبو)، د تار او کېبل عایق، طبي وسایلو او نورو کې په پراخه کچه کارېږي.')
add('Vinyl chloride monomer (VCM) is the initiator of PVC. It is commercially produced by treating acetylene with HCl, as a result it forms an addition product called vinyl chloride in the presence of HgCl₂ or CuCl.','وائنائل کلورائیڈ مونومر (VCM) PVC کا ابتدائی مادہ ہے۔ یہ تجارتی طور پر ایسیٹیلین کو HCl سے عمل کر کے تیار کیا جاتا ہے، جس کے نتیجے میں HgCl₂ یا CuCl کی موجودگی میں وائنائل کلورائیڈ نامی اضافی پیداوار بنتی ہے۔','وینایل کلوراید مونومر (VCM) د PVC پیلوونکی دی. په سوداګریز ډول د اسیتیلین او HCl د تعامل په واسطه تولیدېږي، چې په پایله کې د HgCl₂ یا CuCl په شتون کې وینایل کلوراید نومی اضافي محصول جوړوي.')
add('At 70-80°C vinyl chloride monomers polymerize and polyvinyl chloride of high molecular weight is produced.','70-80°C پر وائنائل کلورائیڈ مونومرز پولیمرائز ہوتے ہیں اور زیادہ سالماتی وزن والا پولی وائنائل کلورائیڈ بنتا ہے۔','په 70-80°C کې وینایل کلوراید مونومرونه پولیمرایز کېږي او د لوړ مالیکولي وزن پولي وینایل کلوراید تولیدېږي.')
visual('chem12-p163-pvc',pvc)
add('2. Condensation Polymers','2. تکثیفی پولیمرز','2. تکثیفي پولیمرونه','heading')
add('The polymers which are formed by the combination of two or more monomers with the elimination of small molecules such as water, hydrogen chloride (HCl), ammonia (NH₃) or methanol (CH₃OH) etc., are known as condensation polymers. If the carbon–chain back bone has two functional group attached to it, a condensation reaction can occur involving polymerization and the polymer produced in such a case is called condensation polymer. e.g., nylon 6, 6 (six carbon atom in each monomer) is formed by the condensation of hexamethylene diamine with adipic acid (hexanedioic acid).','وہ پولیمرز جو دو یا زیادہ مونومرز کے ملنے سے پانی، ہائیڈروجن کلورائیڈ (HCl)، امونیا (NH₃) یا میتھانول (CH₃OH) وغیرہ جیسے چھوٹے سالمات کے اخراج کے ساتھ بنتے ہیں، تکثیفی پولیمرز کہلاتے ہیں۔ اگر کاربن زنجیر کے ڈھانچے سے دو فعلی گروپ جڑے ہوں تو پولیمرائزیشن پر مشتمل تکثیفی تعامل ہو سکتا ہے اور ایسی صورت میں بننے والے پولیمر کو تکثیفی پولیمر کہتے ہیں۔ مثلاً نائیلون 6، 6 (ہر مونومر میں چھ کاربن ایٹم) ہیکسا میتھیلین ڈائی امائن اور ایڈیپک ایسڈ (ہیکسین ڈائی اوئک ایسڈ) کی تکثیف سے بنتا ہے۔','هغه پولیمرونه چې د دوو یا ډېرو مونومرونو د یو ځای کېدو په واسطه د کوچنیو مالیکولونو لکه اوبو، هایدروجن کلوراید (HCl)، امونیا (NH₃) یا میتانول (CH₃OH) او نورو په ایستلو سره جوړېږي، تکثیفي پولیمرونه بلل کېږي. که د کاربني ځنځیر له ملا تیر سره دوه فعال ګروپونه تړلي وي، د پولیمرایزېشن لرونکی تکثیفي تعامل کېدای شي او په داسې حالت کې جوړ شوی پولیمر تکثیفي پولیمر بلل کېږي. د بېلګې په توګه نایلون 6، 6 (په هر مونومر کې شپږ کاربني اټومونه) د هېکسا میتیلین ډای امین او اډیپیک اسید (هېکسان ډای ویک اسید) د تکثیف په واسطه جوړېږي.')
